1	// All money in splitbill is an integer number of cents. Never use floats for
2	// amounts: see .claude/skills/handling-money/references/rules.md.
3	
4	/** Format integer cents as a fixed 2-decimal string, e.g. 1005 -> "10.05". */
5	export function formatCents(cents: number): string {
6	  if (!Number.isInteger(cents)) {
7	    throw new Error(`formatCents expects an integer number of cents, got ${cents}`);
8	  }
9	  const sign = cents < 0 ? "-" : "";
10	  const abs = Math.abs(cents);
11	  const whole = Math.floor(abs / 100);
12	  const frac = String(abs % 100).padStart(2, "0");
13	  return `${sign}${whole}.${frac}`;
14	}
15	
16	/** Parse a decimal amount string ("10.05") into integer cents (1005). */
17	export function parseCents(input: string): number {
18	  const trimmed = input.trim();
19	  const match = /^(-?)(\d+)(?:\.(\d{1,2}))?$/.exec(trimmed);
20	  if (!match) {
21	    throw new Error(`invalid amount: ${input}`);
22	  }
23	  const [, sign, whole, frac = ""] = match;
24	  const paddedFrac = frac.padEnd(2, "0");
25	  const cents = Number(whole) * 100 + Number(paddedFrac);
26	  return sign === "-" ? -cents : cents;
27	}
28	
29	/**
30	 * Split an integer amount of cents evenly across member ids.
31	 *
32	 * SEEDED DEFECT (issue #2): this floors every share and drops the
33	 * remainder instead of handing the leftover cents to the first N members,
34	 * so the shares can sum to less than totalCents. `bun test` does not catch
35	 * this because the baseline tests only split amounts that divide evenly.
36	 * The correct remainder rule is documented in
37	 * .claude/skills/handling-money/references/rules.md.
38	 */
39	export function splitCents(totalCents: number, memberIds: string[]): Record<string, number> {
40	  if (memberIds.length === 0) {
41	    throw new Error("cannot split among zero members");
42	  }
43	  const share = Math.floor(totalCents / memberIds.length);
44	  const shares: Record<string, number> = {};
45	  for (const id of memberIds) {
46	    shares[id] = share;
47	  }
48	  return shares;
49	}
50	
51	export function sumCents(values: number[]): number {
52	  return values.reduce((acc, v) => acc + v, 0);
53	}
