5	export interface NewExpenseInput {
6	  groupId: string;
7	  payerId: string;
8	  amountCents: number;
9	  description: string;
10	  splitAmong: string[];
11	  /** Override the created_at timestamp (used by seed data to keep insertion order distinct). */
12	  createdAt?: string;
13	}
14	
15	export interface ExpenseWithPayer extends Expense {
16	  payerName: string;
17	}
18	
19	export function createExpense(db: Database, input: NewExpenseInput): Expense {
20	  const expense: Expense = {
21	    id: crypto.randomUUID(),
22	    groupId: input.groupId,
23	    payerId: input.payerId,
24	    amountCents: input.amountCents,
25	    description: input.description,
26	    createdAt: input.createdAt ?? new Date().toISOString(),
27	  };
28	  const shares = splitCents(input.amountCents, input.splitAmong);
29	
30	  const insertExpense = db.query(
31	    `INSERT INTO expenses (id, group_id, payer_id, amount_cents, description, created_at)
32	     VALUES (?, ?, ?, ?, ?, ?)`,
33	  );
34	  const insertShare = db.query(
35	    `INSERT INTO expense_shares (expense_id, member_id, share_cents) VALUES (?, ?, ?)`,
36	  );
37	  db.transaction(() => {
38	    insertExpense.run(expense.id, expense.groupId, expense.payerId, expense.amountCents, expense.description, expense.createdAt);
39	    for (const [memberId, shareCents] of Object.entries(shares)) {
40	      insertShare.run(expense.id, memberId, shareCents);
41	    }
42	  })();
43	
44	  return expense;
45	}

